handle.overwrite_arrow_reader(arrow::batch_reader(arrow_schema, [batch]), &options)?;
assert_eq!(handle.read_arrow_field(&options)?, schema);
assert_eq!((handle.row_size()?, handle.column_size()?), (2, 2));

