// And the file written before the column existed reads it as null.
for batch in table.scan(None)? {
    let batch = batch?;
    assert_eq!(batch.num_columns(), 2);
    assert_eq!(batch.column_by_name("quantity").unwrap().null_count(), batch.num_rows());
}

